'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
const state={shells:2450,harvest:0,player:{x:815,y:578},target:{x:815,y:578},outfit:0,sound:false};
const $=s=>document.querySelector(s); let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function ellipse(x,y,rx,ry,color,c=ctx){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
function poly(points,color,c=ctx){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill()}
function line(points,color,width=3,c=ctx){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke()}
function tree(x,y,size=1){ctx.save();ctx.translate(x,y);ctx.scale(size,size);ellipse(0,12,41,13,'#729c7440');poly([[-7,0],[7,0],[5,-65],[-4,-65]],'#a58d72');ellipse(-18,-72,34,34,'#a9c98a');ellipse(18,-75,34,37,'#98ba7b');ellipse(0,-103,35,33,'#bdd69a');ellipse(-13,-115,18,12,'#c9dfa7');ctx.restore()}
function bush(x,y,s=1,flowers=false){ellipse(x,y+5,25*s,9*s,'#699b6840');ellipse(x-12*s,y-7*s,19*s,16*s,'#9ebc85');ellipse(x+10*s,y-10*s,23*s,20*s,'#aeca92');ellipse(x,y-20*s,18*s,17*s,'#bbd59e');if(flowers)for(let i=0;i<7;i++){let a=i*2.4;ellipse(x+Math.sin(a)*20*s,y-12*s+Math.cos(a)*12*s,5*s,4*s,i%2?'#f3c5c7':'#e7d6ed')}}
function house(){ellipse(710,489,140,35,'#7e9a6240');poly([[598,358],[738,320],[828,369],[691,414]],'#fff1d7');poly([[598,358],[691,402],[691,488],[598,443]],'#f3e8cf');poly([[691,402],[828,359],[828,446],[691,488]],'#e1d8bd');poly([[577,361],[649,265],[758,288],[696,402]],'#b6bca7');poly([[649,265],[758,288],[846,357],[696,402]],'#ccd0b5');for(let i=0;i<8;i++)line([[664+i*10,280+i*2],[711+i*15,388-i*5]],'#a9b39766',2);poly([[780,300],[799,294],[799,335],[780,341]],'#d4c7ad');poly([[776,298],[794,290],[805,296],[785,304]],'#f2e4cb');poly([[714,414],[749,403],[749,470],[714,481]],'#b79c7c');poly([[720,418],[742,411],[742,445],[720,453]],'#d7e1c5');ellipse(741,455,2,3,'#f3e9c7');poly([[771,405],[806,394],[806,424],[771,435]],'#9fb9b0');line([[789,400],[789,430]],'#f6edda',4);line([[772,420],[806,409]],'#f6edda',4);poly([[613,382],[647,392],[647,422],[613,410]],'#9fb9b0');line([[630,388],[630,416]],'#fff0db',4);poly([[702,481],[754,465],[772,477],[719,495]],'#d3c4a6');poly([[719,495],[772,477],[772,484],[719,503]],'#bcae91');bush(603,448,.85,true);bush(818,446,.9,true)}
function farm(){poly([[943,552],[1069,506],[1187,565],[1062,622]],'#b49a77');poly([[950,550],[1067,513],[1175,566],[1061,613]],'#c9ad87');for(let r=0;r<3;r++)for(let col=0;col<5;col++){let x=971+col*24+r*27,y=548-col*8+r*18,p=economy.plot(r*5+col);ellipse(x,y,11,5,'#9b815e77');if(p.stage!=='empty'){let ready=p.stage==='ready';line([[x,y],[x,y-(ready?16:8)]],'#779b62',3);line([[x,y-3],[x-6,y-10]],'#94b87a',3);if(ready){if(p.crop==='cotton')ellipse(x,y-17,7,5,'#fff7ea');else poly([[x-3,y],[x+4,y],[x+1,y+10]],'#edb27a')}}}}

function draw(t=0){const dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=w*dpr;canvas.height=h*dpr}ctx.setTransform(canvas.width/1600,0,0,canvas.height/900,0,0);ctx.clearRect(0,0,1600,900);ctx.fillStyle='#b7ddd6';ctx.fillRect(0,0,1600,900);
if(typeof HousingUI!=='undefined'&&HousingUI.aerial){HousingUI.drawAerial(ctx,t);return}

for(let i=0;i<45;i++){let x=(i*173+Math.sin(t/3000+i)*12)%1650,y=170+(i*97)%720;line([[x,y],[x+13,y+1],[x+21,y-1]],'#e9f6e747',2)}
ellipse(864,577,548,244,'#a4d2c7');ellipse(814,526,538,245,'#dfd8b5');ellipse(805,501,522,236,'#f0e5c6');ellipse(795,465,495,228,'#bdd2a0');ellipse(795,456,482,214,'#c8d9ac');
poly([[681,447],[729,466],[783,522],[875,551],[973,602],[1023,673],[979,696],[922,627],[843,591],[742,563],[685,501]],'#e8ddbb');poly([[760,541],[813,564],[721,640],[616,672],[568,655],[689,604]],'#e8ddbb');
for(let i=0;i<100;i++){let x=360+(i*73)%883,y=295+(i*43)%390;if(((x-795)/450)**2+((y-460)/196)**2<.94){line([[x,y],[x-2,y-5]],'#9ebc8b66',1.5);if(i%6===0){ellipse(x,y-4,2,2,'#f7efd7');ellipse(x+4,y-1,2,2,'#fff5db')}}}
[[461,407,1.2],[553,324,1.15],[875,293,1.05],[990,341,1.2],[1154,446,1.15],[433,520,.9],[524,600,1],[1114,626,.9]].forEach(v=>tree(...v));house();farm();if(typeof HousingUI!=='undefined')HousingUI.drawTower(ctx);
[[872,376,.8,true],[558,471,.65,true],[1019,395,.7,true],[1163,526,.75,false],[663,646,.6,true],[926,668,.8,true]].forEach(v=>bush(...v));
ellipse(state.player.x,state.player.y+5,20,7,'#75956c42');
Wardrobe.draw(ctx,state.player.x,state.player.y,108);
// Shoreline stones and a small wooden jetty.
for(let i=0;i<6;i++)ellipse(1180+i*12,652+i*3,12,7,'#c7cbb7');poly([[1005,690],[1050,672],[1155,740],[1113,761]],'#c0ac8c');for(let i=0;i<7;i++)line([[1012+i*15,695+i*9],[1050+i*15,680+i*9]],'#ead7b4',3);
$('#playerLabel').style.left=(state.player.x/16)+'%';$('#playerLabel').style.top=((state.player.y-56)/9)+'%';
}
const keys=new Set();let previous=0;function animate(t){const dt=Math.min((t-previous)/1000,.05);previous=t;let dx=state.target.x-state.player.x,dy=state.target.y-state.player.y;let kx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),ky=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);if(kx||ky){state.target.x=state.player.x+kx*20;state.target.y=state.player.y+ky*20;dx=kx*20;dy=ky*20}let dist=Math.hypot(dx,dy);if(dist>2){let step=Math.min(125*dt,dist),x=state.player.x+dx/dist*step,y=state.player.y+dy/dist*step;if(walkable(x,y)){state.player.x=x;state.player.y=y}else state.target={...state.player}}draw(t);requestAnimationFrame(animate)}
function walkable(x,y){if(typeof HousingUI!=='undefined'&&HousingUI.aerial)return false;return ((x-795)/430)**2+((y-490)/185)**2<1&&!(x>588&&x<840&&y>320&&y<490)}
canvas.addEventListener('click',e=>{if(HousingUI.aerial)return;let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1600,y=(e.clientY-r.top)/r.height*900;if(walkable(x,y))state.target={x,y};else toast('산책길 안쪽을 눌러 주세요 🌿')});
const mini=$('#mini').getContext('2d');ellipse(110,79,86,49,'#e9dfbd',mini);ellipse(108,73,81,45,'#b9cea1',mini);poly([[85,59],[104,51],[120,62],[100,70]],'#f3e7ce',mini);poly([[82,59],[100,40],[122,60],[100,66]],'#a9b99a',mini);line([[100,72],[111,91],[143,102]],'#e7d8b5',7,mini);ellipse(114,91,4,4,'#b697b8',mini);poly([[144,76],[163,70],[181,82],[161,90]],'#b89c78',mini);
function modal(title,body){$('#modal').classList.remove('wardrobe-modal');keys.clear();state.target={...state.player};$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal()}
$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#farm').onclick=()=>toast('선택한 씨앗을 빈 밭 칸에 심고, 반짝이는 칸을 눌러 수확하세요.');

const menus={wardrobe:['오늘의 옷장','마음에 드는 기본 코디를 골라 보세요.'],bag:['나의 작은 가방','오늘 모은 소중한 것들을 담아 두었어요.'],craft:['포근 의상 공방','나만의 옷을 만드는 작업대예요.'],shop:['햇살 부티크','새로운 옷을 만나는 작은 편집숍이에요.'],market:['마을 광장 장터','이웃의 취향이 담긴 물건을 만나는 곳이에요.'],decorate:['섬 꾸미기','나만의 쉼터를 채워 갈 준비를 해요.']};
function openMenu(id){if(id==='market'){CommunityUI.market();return}if(id==='decorate'){HousingUI.open();return}if(id==='shop'){FashionUI.shop();return}if(id==='craft'){FashionUI.workshop();return}if(id==='bag'){LifeUI.bag();return}if(id==='wardrobe'){Wardrobe.open(modal);return}if(id==='home'){toast('지금은 나의 섬에 있어요');return}let [title,description]=menus[id];let content=`<p>${description}</p>`;if(id==='bag'){content+=`<div class="cards"><div class="item"><span>🥕</span>몽글당근 × ${state.harvest}</div><div class="item"><span>◒</span>조개 × ${state.shells.toLocaleString()}</div></div>`}else{content+='<div class="cards"><div class="item"><span>✧</span>준비 중인 공간</div><div class="item"><span>❀</span>새로운 이야기를 기다려요</div></div><p>현재는 메인 화면 UI 프로토타입입니다. 제작·구매·거래·가구 배치는 다음 단계에서 연결합니다.</p>'}modal(title,content);}

document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>openMenu(b.dataset.menu));
function quests(){const d=economy.data;modal('오늘의 작은 부탁',`<p>몽글당근 수확하기 · ${Math.min(3,d.carrotsHarvested)} / 3</p><p>밭 칸에 당근을 심고 15초 뒤 수확하세요.<br>보상: 달빛 마법 가루 1개 · 유니크 의상 합성 재료</p><button class="primary" id="questReward" ${d.carrotsHarvested<3||d.claimed.includes('first-harvest')?'disabled':''}>${d.claimed.includes('first-harvest')?'보상 수령 완료':'퀘스트 보상 받기'}</button><p id="questResult" role="status"></p>`);$('#questReward').onclick=()=>{const result=economy.claimQuest();$('#questResult').textContent=result.message;$('#questReward').disabled=economy.data.claimed.includes('first-harvest')}}

$('#questbook').onclick=quests;document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=quests);
$('#letter').onclick=()=>modal('포근섬에 온 걸 환영해요', '<p>포근이에게,<br><br>바다 건너 이 작은 섬에 와 줘서 고마워요. 오늘은 집 앞 텃밭을 돌보고, 햇살 아래 천천히 걸어 보는 건 어때요?<br><br>이곳에서는 당신의 속도로 하루를 채워도 괜찮아요.<br><br>포근섬 주민 일동 드림 ❀</p>');
$('#event').onclick=()=>modal('꽃바람이 불어오는 계절','<p>봄날의 포근섬에 오신 것을 환영해요.<br>수국 꽃길, 작은 텃밭, 햇살이 드는 우리 집.<br>오늘은 어디에서 쉬어 갈까요?</p>');
$('#map').onclick=()=>modal('나의 포근섬 지도','<p>현재 지역: 우리 집 앞마당</p><div class="cards"><div class="item"><span>⌂</span>우리 집</div><div class="item"><span>♧</span>몽글 텃밭</div><div class="item"><span>⚑</span>마을 광장 · 장터 메뉴</div><div class="item"><span>≈</span>바닷가 · 낚시 가능</div></div>');
$('#settings').onclick=()=>{modal('포근한 환경 설정','<label class="switch">효과음<input id="audioSwitch" type="checkbox"></label><p>화면은 16:9 비율을 유지합니다. 작은 화면에서는 가로 방향을 권장해요.</p>');$('#audioSwitch').checked=state.sound;$('#audioSwitch').onchange=e=>setSound(e.target.checked)};
let audioContext;function setSound(on){state.sound=on;$('#sound').setAttribute('aria-pressed',String(on));$('#sound').setAttribute('aria-label',on?'효과음 끄기':'효과음 켜기');$('#sound').style.color=on?'#7d9d6a':'';if(on){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();let o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=660;o.connect(g);g.connect(audioContext.destination);g.gain.setValueAtTime(.05,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.4);o.start();o.stop(audioContext.currentTime+.4)}catch{toast('이 브라우저는 효과음을 지원하지 않아요')}}}
$('#sound').onclick=()=>{setSound(!state.sound);toast(state.sound?'효과음이 켜졌어요':'효과음을 껐어요')};$('#help').onclick=()=>modal('포근섬에서 보내는 하루','<p>빈 땅을 클릭하거나 WASD · 방향키로 이동하세요.<br>텃밭 버튼을 누르면 당근을 수확할 수 있어요.<br>하단 메뉴는 숫자 1–7로도 열 수 있어요.<br>열린 창은 Esc로 닫을 수 있어요.<br><br>옷장에서 코디를 바꾸면 섬의 아바타에도 바로 반영돼요. 원본 JPG 또는 연결한 PNG 레이어를 표시합니다.</p>');$('#currency').onclick=()=>toast('조개는 수확·채집·낚시로 모으고 씨앗 구매에 사용해요');
window.addEventListener('keydown',e=>{if($('#modal').open)return;if(/^[1-7]$/.test(e.key)){openMenu(['home','wardrobe','bag','craft','shop','market','decorate'][+e.key-1]);return}if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();keys.add(e.key)}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());$('#modal').addEventListener('close',()=>keys.clear());
requestAnimationFrame(animate);
